// 또는 프로젝트별: path.resolve('.claude/skills/asan-pptx')
const LOGO = path.resolve(SKILL_DIR, 'assets/Asan_Medical_Center_logo_transparent.png');
const LOGO_W = path.resolve(SKILL_DIR, 'assets/Asan_Medical_Center_logo_w.png');
